import * as React from "react"
import {
  AssistantRuntimeProvider,
  AuiConfig,
  Suggestions,
  Tools,
  useAui,
  useAuiState,
  type AssistantRuntime,
} from "@assistant-ui/react"

import { Thread } from "@/components/assistant-ui/elements/thread.aui"

import {
  AdkContextMeter,
  AdkFollowUps,
  AdkMessageAuthor,
  AdkModelSection,
  AdkToolFallback,
} from "./adk"
import { adkToolkit, delegationToolkit } from "./adk-toolkit"
import {
  AssistantSettingsContext,
  useAssistantSettings,
  type ApprovalView,
  type AssistantWelcome,
  type AuthRequestHandler,
} from "./assistant-context"
import { AssistantCommandMenu, type AssistantCommand } from "./commands"
import type { ModelSettings } from "./model-settings"
import {
  MessageSources,
  SourcedMarkdownText,
  type AssistantSourcesConfig,
} from "./sources"
import type { AdkArtifactsApi } from "./use-adk-assistant"

type SuggestionList = Parameters<typeof Suggestions>[0]
type Toolkit = NonNullable<Parameters<typeof Tools>[0]>["toolkit"]

/** What every assistant surface (screen, modal) is configured with. */
export type AssistantOptions = {
  /** From `useAdkAssistant` (or any assistant-ui runtime). */
  runtime: AssistantRuntime
  /** From `useAdkAssistant`; enables artifact downloads. */
  artifacts?: AdkArtifactsApi
  /** Completes ADK sign-in requests; see `AuthRequestHandler`. */
  onAuthRequest?: AuthRequestHandler
  /** The assistant's name. Default "Assistant". */
  title?: string
  /** Shown above the composer while a conversation is empty. */
  welcome?: AssistantWelcome
  /** Starter prompts for an empty conversation. */
  suggestions?: SuggestionList
  /** Your tool UIs, merged over the ADK ones (`defineToolkit`). */
  toolkit?: Toolkit
  /** `/` commands in the composer; see `AssistantCommand`. */
  commands?: AssistantCommand[]
  /**
   * Shown at the top of the composer: what the agent gets with the next
   * message besides the text, e.g. the page the person is on (`runState` on
   * `useAdkAssistant` sends it).
   */
  composerContext?: React.ReactNode
  /** Persistent progress or task controls just above the composer. */
  composerLead?: React.ComponentType
  /**
   * Controls in the composer's bottom row, after the model section: e.g. a
   * menu choosing what the agent may use with the next message
   * (`composerChip` matches their look).
   */
  composerActions?: React.ReactNode
  /** Right-aligned controls immediately before Send. */
  composerTrailingActions?: React.ComponentType
  /**
   * How tools that need the person's approval (ADK `require_confirmation`)
   * ask for it, by tool name: a friendly title and a preview of what will
   * happen, in place of the tool's name and raw arguments.
   */
  approvals?: Readonly<Record<string, ApprovalView>>
  /** Beside each reply's copy and retry actions, e.g. its timing and tokens. */
  messageMeta?: React.ComponentType
  /**
   * Above the composer once a reply is done, in place of the default: the
   * follow-up questions the agent server wrote for the reply
   * (`suggestFollowUps` on `useAdkAssistant`), or the runtime's own
   * suggestions while there are none (`AdkFollowUps`).
   */
  followUps?: React.ComponentType
  /**
   * Opens an artifact picked in the top bar's menu, e.g. in a canvas; it
   * downloads otherwise.
   */
  onOpenArtifact?: (name: string) => void
  /**
   * Cited sources: reads the passages in tool results, each with a ref the
   * agent cites as "[S3]", and draws the citations as numbered chips with a
   * list of the documents under the answer.
   */
  sources?: AssistantSourcesConfig
  /**
   * What the app's agents are called, by their ADK names, e.g. the
   * specialists an ADK supervisor hands requests to; others are shown by
   * their names. A call handing a request to one of them shows as asking it.
   */
  agents?: Readonly<Record<string, string>>
  /**
   * Shows the context meter in the composer, after the model section: how
   * much of the model's context window the conversation holds, what's left
   * and when it's compacted, from an agent server that reports it in the
   * session's state (`forge:context:<agent>`, forge_common's
   * `ContextWindowPlugin`). A model with a `contextWindow` in the model
   * section sets the window (the next request runs on it). Nothing shows
   * until there's a window to measure against. Default true.
   */
  showContext?: boolean
} & (
  | { showModels?: false; modelSettings?: ModelSettings }
  | {
      /**
       * Shows the model section in the composer: the agent's name, its model
       * (when there's more than one) and the thinking level.
       */
      showModels: true
      /** From `useAdkAssistant`: the choices, and what runs send. */
      modelSettings: ModelSettings
    }
)

const titleFrom = (text: string) => {
  const line = text.trim().split("\n")[0] ?? ""
  return line.length > 60 ? `${line.slice(0, 57).trimEnd()}…` : line
}

/**
 * ADK sessions have no titles, so a conversation is named after its first
 * message once it exists on the server. Adapters that persist titles keep it.
 */
function AutoTitle() {
  const aui = useAui()
  const untitled = useAuiState((s) => {
    const item = s.threads.threadItems.find(
      (t) => t.id === s.threads.mainThreadId
    )
    return Boolean(item?.remoteId) && !item?.title
  })
  const firstMessage = useAuiState((s) => {
    const message = s.thread.messages.find((m) => m.role === "user")
    const part = message?.content.find((p) => p.type === "text")
    return part?.type === "text" ? part.text : undefined
  })
  React.useEffect(() => {
    if (untitled && firstMessage) {
      aui.threads.item("main").rename(titleFrom(firstMessage))
    }
  }, [aui, untitled, firstMessage])
  return null
}

/**
 * The runtime, the ADK tool UIs and the settings every assistant part reads.
 * `AssistantScreen` and `AssistantModal` render it for you; use it directly
 * to lay the parts out yourself.
 */
function AssistantProvider({
  runtime,
  toolkit,
  suggestions,
  artifacts,
  onAuthRequest,
  title = "Assistant",
  welcome,
  commands,
  composerContext,
  composerLead,
  composerActions,
  composerTrailingActions,
  approvals,
  messageMeta,
  followUps,
  onOpenArtifact,
  sources,
  agents,
  showContext,
  showModels,
  modelSettings,
  children,
}: AssistantOptions & { children: React.ReactNode }) {
  const config = React.useMemo(
    () =>
      AuiConfig({
        tools: Tools({
          toolkit: {
            ...adkToolkit,
            ...(agents && delegationToolkit(agents)),
            ...toolkit,
          },
        }),
        ...(suggestions && { suggestions: Suggestions(suggestions) }),
      }),
    [toolkit, suggestions, agents]
  )
  const settings = React.useMemo(
    () => ({
      onAuthRequest,
      artifacts,
      welcome,
      title,
      commands,
      composerContext,
      composerLead,
      composerActions,
      composerTrailingActions,
      approvals,
      messageMeta,
      followUps,
      onOpenArtifact,
      sources,
      agents,
      showContext,
      showModels,
      modelSettings,
    }),
    [
      onAuthRequest,
      artifacts,
      welcome,
      title,
      commands,
      composerContext,
      composerLead,
      composerActions,
      composerTrailingActions,
      approvals,
      messageMeta,
      followUps,
      onOpenArtifact,
      sources,
      agents,
      showContext,
      showModels,
      modelSettings,
    ]
  )

  return (
    <AssistantSettingsContext.Provider value={settings}>
      <AssistantRuntimeProvider runtime={runtime} config={config}>
        <AutoTitle />
        {children}
      </AssistantRuntimeProvider>
    </AssistantSettingsContext.Provider>
  )
}

function AssistantWelcomeMessage() {
  const { welcome } = useAssistantSettings()
  return (
    <div
      data-slot="assistant-welcome"
      className="mb-6 flex flex-col gap-2 px-2"
    >
      <p className="text-[1.3125rem] font-medium tracking-[-.5px] text-foreground">
        {welcome?.title ?? "How can I help?"}
      </p>
      {welcome?.description && (
        <p className="text-sm text-muted-foreground">{welcome.description}</p>
      )}
    </div>
  )
}

function AssistantComposerContext() {
  const { composerContext } = useAssistantSettings()
  return <>{composerContext}</>
}

/**
 * The composer's bottom row: the model section, the context meter (each
 * when it's on), then the app's controls.
 */
function AssistantComposerActions() {
  const {
    showModels,
    showContext = true,
    composerActions,
  } = useAssistantSettings()
  return (
    <>
      {showModels && <AdkModelSection />}
      {showContext && <AdkContextMeter />}
      {composerActions}
    </>
  )
}

const threadComponents = {
  Welcome: AssistantWelcomeMessage,
  ToolFallback: AdkToolFallback,
  MessageHeader: AdkMessageAuthor,
  Text: SourcedMarkdownText,
  MessageFooter: MessageSources,
}

/**
 * The conversation and composer with the Forge and ADK parts: welcome, ADK
 * tool cards, agent labels, and the composer's context, model section,
 * context meter and `/` commands when they're configured. Render it inside
 * `AssistantProvider`.
 */
function AssistantThread() {
  const {
    commands,
    composerContext,
    composerLead,
    composerTrailingActions,
    messageMeta,
    followUps,
  } = useAssistantSettings()
  const hasCommands = Boolean(commands?.length)
  const hasContext = composerContext != null
  const components = React.useMemo(
    () => ({
      ...threadComponents,
      ...(hasContext && { ComposerHeader: AssistantComposerContext }),
      ...(composerLead && { ComposerLead: composerLead }),
      ...(composerTrailingActions && {
        ComposerTrailingActions: composerTrailingActions,
      }),
      // The model section, the context meter and the app's controls, each when it's on.
      ComposerActions: AssistantComposerActions,
      ...(hasCommands && { ComposerTriggers: AssistantCommandMenu }),
      ...(messageMeta && { MessageMeta: messageMeta }),
      // The agent server's follow-up questions, unless the app has its own.
      FollowUps: followUps ?? AdkFollowUps,
    }),
    [
      hasContext,
      hasCommands,
      messageMeta,
      followUps,
      composerLead,
      composerTrailingActions,
    ]
  )
  return (
    <Thread
      components={components}
      placeholder={
        hasCommands ? "Send a message, or type / for commands..." : undefined
      }
    />
  )
}

export { AssistantProvider, AssistantThread }

import * as React from "react"
import {
  unstable_useSlashCommandAdapter,
  useAui,
  type AssistantClient,
  type Unstable_TriggerItem,
  type Unstable_TriggerMatcher,
} from "@assistant-ui/react"

import { ComposerTriggerPopover } from "@/components/assistant-ui/elements/composer-trigger-popover.aui"
import { Icon } from "@/components/forge/icon"
import type { IconProp } from "@/components/forge/icons"

import { useAssistantSettings } from "./assistant-context"

/**
 * A `/` command in the composer. What picking it does depends on its fields:
 *
 * - `execute`: runs in the app (start a conversation, open a sheet…); the
 *   typed `/command` is removed.
 * - `prompt`: fills the composer with the prompt, and sends it with `send`.
 * - neither: leaves `/id ` in the composer for the user to add arguments to,
 *   and the agent receives the command as text (handle it in its
 *   instructions).
 */
export type AssistantCommand = {
  /** Typed after the slash: `deploy` is `/deploy`. */
  id: string
  description?: string
  /** A Forge icon name or a Hugeicons glyph. */
  icon?: IconProp
  prompt?: string
  /** With `prompt`: send it straight away instead of leaving it to edit. */
  send?: boolean
  execute?: (aui: AssistantClient) => void
}

// Commands only open from a `/` at the very start of the message, so a path
// or a fraction later in the text never pops the menu.
const atStartOfMessage: Unstable_TriggerMatcher = (text, char, cursor) => {
  if (!text.startsWith(char)) return null
  const query = text.slice(char.length, cursor)
  return /\s/u.test(query) ? null : { query, offset: 0, endOffset: cursor }
}

function runCommand(command: AssistantCommand, aui: AssistantClient) {
  // The popover has removed the typed `/query` by now.
  const rest = aui.composer.getState().text.trimStart()
  if (command.execute) {
    command.execute(aui)
  } else if (command.prompt !== undefined) {
    aui.composer.setText(rest ? `${command.prompt} ${rest}` : command.prompt)
    if (command.send) aui.composer.send()
  } else {
    aui.composer.setText(`/${command.id} ${rest}`)
  }
}

// assistant-ui also matches descriptions; commands whose name starts with the
// query come first, then other name matches, then description matches.
const rank = (item: Unstable_TriggerItem, query: string) => {
  const id = item.id.toLowerCase()
  if (id.startsWith(query)) return 0
  return id.includes(query) ? 1 : 2
}

type TriggerAdapter = ReturnType<
  typeof unstable_useSlashCommandAdapter
>["adapter"]

function byName(adapter: TriggerAdapter): TriggerAdapter {
  return {
    ...adapter,
    search: (query) => {
      const lower = query.toLowerCase()
      return [...(adapter.search?.(query) ?? [])].sort(
        (a, b) => rank(a, lower) - rank(b, lower)
      )
    },
  }
}

type GlyphComponent = React.FC<{ className?: string }>

// One stable component per icon, so the popover's icon map never remounts.
const glyphs = new Map<IconProp, GlyphComponent>()
function glyphFor(icon: IconProp): GlyphComponent {
  let glyph = glyphs.get(icon)
  if (!glyph) {
    glyph = ({ className }) => <Icon icon={icon} className={className} />
    glyphs.set(icon, glyph)
  }
  return glyph
}

/**
 * The `/` command menu above the composer, for `AssistantScreen`'s
 * `commands`. Arrow keys move, Enter or Tab picks, Escape closes.
 */
function AssistantCommandMenu() {
  const { commands = [] } = useAssistantSettings()
  const aui = useAui()
  const slash = unstable_useSlashCommandAdapter({
    commands: commands.map((command) => ({
      id: command.id,
      description: command.description,
      icon: command.id,
      // The popover removes the typed `/query` as it calls this, and the
      // composer state reflects that from the next task.
      execute: () => setTimeout(() => runCommand(command, aui)),
    })),
    removeOnExecute: true,
  })
  const adapter = React.useMemo(() => byName(slash.adapter), [slash.adapter])
  const iconMap = React.useMemo(
    () =>
      Object.fromEntries(
        commands.flatMap((command) =>
          command.icon ? [[command.id, glyphFor(command.icon)]] : []
        )
      ),
    [commands]
  )

  return (
    <ComposerTriggerPopover
      char="/"
      matcher={atStartOfMessage}
      adapter={adapter}
      action={slash.action}
      iconMap={iconMap}
      emptyItemsLabel="No matching commands"
    />
  )
}

export { AssistantCommandMenu }

/**
 * How full an agent's context window is, as the agent server keeps it in the
 * ADK session's state (`forge:context:<agent>`, forge_common's
 * `ContextWindowPlugin`): what its conversation holds, what its model may
 * read, and where it's compacted. The composer's context meter shows it.
 */

/** The state key each agent's context window is kept under, before its name. */
export const CONTEXT_STATE_PREFIX = "forge:context:"

/** An agent's context window, as the agent server keeps it. */
export type AgentContext = {
  /** What its conversation holds: its last request, or once the model answered, that and the reply. */
  tokens: number
  /** What a request may hold: the model's window less what's kept for the reply. */
  limit: number
  /** Where it's compacted. */
  threshold: number
  /** The model's whole window, and of it what's kept for the reply. */
  window?: number
  reply?: number
  /** The threshold as a share of the limit, e.g. 0.8. */
  share?: number
  /** Whether it compacts at the threshold by itself; otherwise only when asked. */
  auto?: boolean
  /** `estimate`: measured before the request went out; `provider`: what the model reported. */
  counted?: "estimate" | "provider"
  /** The model that last answered it (`provider/model`). */
  model?: string
  compactions?: number
  lastCompaction?: {
    at?: number
    tokensBefore: number
    tokensAfter: number
  }
  /** A compaction was asked for, before its next request. */
  requested?: boolean
  /**
   * It works apart from the conversation (a task, an agent called as a tool,
   * a parallel branch): each call starts from what it was handed.
   */
  apart?: boolean
  /** When it was counted, in seconds since the epoch. */
  updated?: number
}

/** What a model may read, as the model list gives it. */
export type ModelWindow = {
  id: string
  name?: string
  contextWindow?: number
  maxTokens?: number
}

const isNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value)

/** One agent's entry, if it's one the server wrote. */
export function parseAgentContext(value: unknown): AgentContext | undefined {
  if (!value || typeof value !== "object") return undefined
  const raw = value as Record<string, unknown>
  if (!isNumber(raw.tokens) || !isNumber(raw.limit) || raw.limit <= 0) {
    return undefined
  }
  const last = raw.last_compaction as Record<string, unknown> | undefined
  return {
    tokens: raw.tokens,
    limit: raw.limit,
    threshold: isNumber(raw.threshold) ? raw.threshold : raw.limit,
    ...(isNumber(raw.window) && { window: raw.window }),
    ...(isNumber(raw.reply) && { reply: raw.reply }),
    ...(isNumber(raw.share) && { share: raw.share }),
    ...(typeof raw.auto === "boolean" && { auto: raw.auto }),
    ...((raw.counted === "estimate" || raw.counted === "provider") && {
      counted: raw.counted,
    }),
    ...(typeof raw.model === "string" && raw.model && { model: raw.model }),
    ...(isNumber(raw.compactions) && { compactions: raw.compactions }),
    ...(last &&
      isNumber(last.tokens_before) &&
      isNumber(last.tokens_after) && {
        lastCompaction: {
          tokensBefore: last.tokens_before,
          tokensAfter: last.tokens_after,
          ...(isNumber(last.at) && { at: last.at }),
        },
      }),
    ...(raw.requested === true && { requested: true }),
    ...(raw.apart === true && { apart: true }),
    ...(isNumber(raw.updated) && { updated: raw.updated }),
  }
}

/**
 * The agent whose context the composer shows: the conversation's own agent,
 * the one answering when it has an entry, else the one counted last. Agents
 * that work apart from it (a task the agent hands a question to) are left
 * out, since each of their calls starts afresh; only when there's no other
 * is the one counted last shown.
 */
export function currentContext(
  state: Readonly<Record<string, unknown>>,
  agent?: string
): { agent: string; context: AgentContext } | undefined {
  type Found = { agent: string; context: AgentContext }
  const later = (found: Found, than?: Found) =>
    !than || (found.context.updated ?? 0) > (than.context.updated ?? 0)
  let latest: Found | undefined
  let latestApart: Found | undefined
  for (const [key, value] of Object.entries(state)) {
    if (!key.startsWith(CONTEXT_STATE_PREFIX)) continue
    const context = parseAgentContext(value)
    if (!context) continue
    const found = { agent: key.slice(CONTEXT_STATE_PREFIX.length), context }
    if (context.apart) {
      if (later(found, latestApart)) latestApart = found
      continue
    }
    if (agent && found.agent === agent) return found
    if (later(found, latest)) latest = found
  }
  return latest ?? latestApart
}

/**
 * - `clear`: well below where it's compacted;
 * - `near`: within a tenth of it;
 * - `compacting`: past it, so it's compacted before the next request (or,
 *   when it only compacts when asked, would be);
 * - `full`: past what a request may hold.
 */
export type ContextPhase = "clear" | "near" | "compacting" | "full"

export type ContextView = {
  /** Tokens the conversation holds; 0 before the agent has been counted. */
  used: number
  /** What a request may hold. */
  limit: number
  /** Where it's compacted; unknown until the agent has been counted. */
  threshold?: number
  /** `used` and `threshold` as shares of the limit (0–1, `used` may pass 1). */
  usedShare: number
  thresholdShare?: number
  /** Before the limit, and before the compaction (negative once past). */
  left: number
  untilCompaction?: number
  phase: ContextPhase
  auto: boolean
  /** No count yet: the conversation hasn't reached the agent. */
  empty: boolean
  /** The count is an estimate (before a request) rather than the model's. */
  estimated: boolean
  /** The model whose window this is: the one chosen in the composer, else the one that answered. */
  model?: string
  window?: number
  reply?: number
  /** The model chosen in the composer isn't the one the count is from. */
  modelChanged: boolean
  compactions: number
  lastCompaction?: AgentContext["lastCompaction"]
  requested: boolean
}

/**
 * The meter's numbers. A model chosen in the composer (`model`) whose window
 * is known wins over the window the count was made against: the next request
 * runs on it, and the server compacts at the same share of its limit.
 */
export function contextView(
  context: AgentContext | undefined,
  model?: ModelWindow
): ContextView | undefined {
  const modelLimit =
    model && isNumber(model.contextWindow) && model.contextWindow > 0
      ? Math.max(1, model.contextWindow - (model.maxTokens ?? 0))
      : undefined
  if (!context && modelLimit === undefined) return undefined

  // The server's own numbers, unless the next request runs on another model.
  const switched =
    modelLimit !== undefined &&
    context?.model !== undefined &&
    context.model !== model?.id
  const fromModel = modelLimit !== undefined && (!context || switched)
  const limit = fromModel ? modelLimit : context!.limit
  const threshold = !context
    ? undefined
    : fromModel
      ? Math.max(
          1,
          Math.floor(
            limit * (context.share ?? context.threshold / context.limit)
          )
        )
      : context.threshold
  const used = context?.tokens ?? 0

  const phase: ContextPhase =
    used > limit
      ? "full"
      : threshold !== undefined && used >= threshold
        ? "compacting"
        : threshold !== undefined && used >= threshold * 0.9
          ? "near"
          : "clear"

  return {
    used,
    limit,
    ...(threshold !== undefined && {
      threshold,
      thresholdShare: threshold / limit,
      untilCompaction: threshold - used,
    }),
    usedShare: used / limit,
    left: limit - used,
    phase,
    auto: context?.auto ?? true,
    empty: context === undefined,
    estimated: context?.counted === "estimate",
    ...(fromModel
      ? {
          model: model?.name ?? model?.id,
          window: model?.contextWindow,
          reply: model?.maxTokens,
        }
      : {
          // The model that answered, by its name when it's the one chosen.
          ...(context?.model && {
            model:
              model?.id === context.model
                ? (model.name ?? context.model)
                : context.model,
          }),
          ...(context?.window !== undefined && { window: context.window }),
          ...(context?.reply !== undefined && { reply: context.reply }),
        }),
    modelChanged: switched,
    compactions: context?.compactions ?? 0,
    ...(context?.lastCompaction && { lastCompaction: context.lastCompaction }),
    requested: context?.requested ?? false,
  }
}

const compactFormat = new Intl.NumberFormat("en", {
  notation: "compact",
  maximumFractionDigits: 1,
})
const fullFormat = new Intl.NumberFormat("en")

/** Tokens in a few characters: 950, 152.3K, 1.2M. */
export const compactTokens = (tokens: number) =>
  compactFormat.format(Math.max(0, Math.round(tokens)))

/** Tokens in full: 152,340. */
export const fullTokens = (tokens: number) =>
  fullFormat.format(Math.round(tokens))

/** A share as a whole percentage, at least 1% once anything is used. */
export function percent(share: number) {
  if (share <= 0) return "0%"
  return `${Math.max(1, Math.round(share * 100))}%`
}

/**
 * Follow-up questions after a reply, written by the agent server: a run asks
 * for them in its state (`forge:suggest_follow_ups`, which `useAdkAssistant`
 * sends with `suggestFollowUps`), and the server keeps the last reply's in the
 * ADK session's state (`forge:follow_ups`, forge_common's `FollowUpsPlugin`),
 * which the thread shows above the composer.
 */

/** The state key a run asks for follow-ups with: true, or `{ count }`. */
export const FOLLOW_UPS_REQUEST_KEY = "forge:suggest_follow_ups"

/** The state key the last reply's follow-ups are kept under: `{ suggestions }`. */
export const FOLLOW_UPS_STATE_KEY = "forge:follow_ups"

/** The most follow-ups a run may ask for. */
export const MOST_FOLLOW_UPS = 5

/**
 * Whether runs ask for follow-up questions after the reply: true for the
 * server's default number (3), or how many (1–5).
 */
export type FollowUpsOption = boolean | { count?: number }

/** What a run sends for `option`: nothing when it's off. */
export function followUpsRequest(
  option: FollowUpsOption | undefined
): Record<string, unknown> | undefined {
  if (!option) return undefined
  if (option === true || option.count === undefined) {
    return { [FOLLOW_UPS_REQUEST_KEY]: true }
  }
  const count = Math.round(option.count)
  return {
    [FOLLOW_UPS_REQUEST_KEY]: {
      count: Math.min(
        Math.max(Number.isFinite(count) ? count : 1, 1),
        MOST_FOLLOW_UPS
      ),
    },
  }
}

/** The last reply's follow-ups in the session's state; none when it has none. */
export function followUpsOf(
  state: Readonly<Record<string, unknown>>
): string[] {
  const kept = state[FOLLOW_UPS_STATE_KEY]
  if (typeof kept !== "object" || kept === null) return []
  const { suggestions } = kept as { suggestions?: unknown }
  if (!Array.isArray(suggestions)) return []
  return suggestions.filter(
    (each): each is string => typeof each === "string" && each.trim() !== ""
  )
}

import type {
  AssistantSearch,
  AssistantSource,
  AssistantSourcesConfig,
} from "./sources"

/*
 * Citations from Forge's knowledge base searches: a chat agent's knowledge
 * base tool (forge_agent_runtime's KnowledgeBaseTool) and the Forge
 * assistant's search_knowledge_bases answer
 *
 *   { status: "success",
 *     payload: { searched: ["Claims knowledge"],
 *                passages: [{ ref, knowledge_base, knowledge_base_id, document,
 *                             document_id, section, location, text, score }],
 *                organization_id?, note? } }
 *
 * (Forge's tools answer in that envelope; a bare payload reads too), and the
 * agent cites passages by ref ("[KQM4821]"). A chat agent's tool is named
 * whatever its builder called it, so a result is recognised by its shape,
 * not its name.
 */

/** One passage of a knowledge base tool's result. */
export type KnowledgePassage = {
  /** What the answer cites it by, e.g. "KQM4821". */
  ref: string
  /** The name of the knowledge base it's in. */
  knowledge_base?: string
  knowledge_base_id?: string
  /** The document's name, e.g. its filename. */
  document?: string
  document_id?: string
  /** The headings it's under: "Appeals > Denied claims". */
  section?: string
  /** Where in the document: "page 4", "slide 3: Pricing". */
  location?: string
  text?: string
  /** How relevant it is; higher is better. */
  score?: number
  /**
   * The organization whose knowledge base it is, when the search says
   * (the Forge assistant's does): for a link to the document.
   */
  organization_id?: string
}

export type KnowledgeSourcesOptions = {
  /**
   * Where a passage's document opens (the "Open document" link), e.g. its
   * knowledge base's page in Forge with it open; no link without.
   */
  documentHref?: (passage: KnowledgePassage) => string | undefined
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/**
 * A result as ADK delivers it: a value or JSON text, sometimes wrapped as
 * `{ result }`; a Forge tool's in `{ status: "success", payload }`.
 */
function readResult(result: unknown): Record<string, unknown> | undefined {
  let value = result
  if (typeof value === "string") {
    try {
      value = JSON.parse(value)
    } catch {
      return undefined
    }
  }
  if (
    isObject(value) &&
    isObject(value.result) &&
    Object.keys(value).length === 1
  )
    value = value.result
  if (isObject(value) && value.status === "success" && isObject(value.payload))
    value = value.payload
  return isObject(value) ? value : undefined
}

type KnowledgeResult = { searched: string[]; passages: KnowledgePassage[] }

/** A knowledge base search's result; undefined for any other tool's. */
function knowledgeResult(result: unknown): KnowledgeResult | undefined {
  const value = readResult(result)
  if (!value || !Array.isArray(value.passages)) return undefined
  const organization =
    typeof value.organization_id === "string"
      ? value.organization_id
      : undefined
  const passages = value.passages
    .filter(
      (p): p is KnowledgePassage => isObject(p) && typeof p.ref === "string"
    )
    .map((p) => ({ organization_id: organization, ...p }))
  const searched = Array.isArray(value.searched)
    ? value.searched.filter((name): name is string => typeof name === "string")
    : []
  return { searched, passages }
}

/** Identifies a passage's document: two knowledge bases can hold the same filename. */
const documentKey = (passage: KnowledgePassage) =>
  passage.document_id ||
  `${passage.knowledge_base_id ?? passage.knowledge_base ?? ""}/${passage.document ?? ""}`

/**
 * Where in its document a passage is: "Refunds > Eligibility (page 2)". The
 * sources list joins a document's passages with " · ", so one passage's
 * parts don't.
 */
function where({ section, location }: KnowledgePassage): string | undefined {
  if (section && location) return `${section} (${location})`
  return section || location || undefined
}

/**
 * The sources config for agents with Forge knowledge base tools: each
 * passage a search found becomes a source the answer can cite, grouped by
 * document, from the knowledge base named under it; each search call's card
 * says what it searched and found.
 *
 * ```tsx
 * const sources = knowledgeBaseSources()  // once, at module scope
 * <AssistantScreen runtime={runtime} sources={sources} />
 * ```
 */
export function knowledgeBaseSources(
  options: KnowledgeSourcesOptions = {}
): AssistantSourcesConfig {
  return {
    fromToolCall: (_toolName, result) =>
      (knowledgeResult(result)?.passages ?? []).map(
        (passage): AssistantSource => ({
          ref: passage.ref,
          document: {
            key: documentKey(passage),
            title: passage.document || "Untitled document",
            subtitle: passage.knowledge_base || undefined,
            href: options.documentHref?.(passage),
          },
          location: where(passage),
          excerpt: passage.text || undefined,
        })
      ),
    searchOf: (_toolName, result): AssistantSearch | undefined => {
      const found = knowledgeResult(result)
      if (!found) return undefined
      return {
        searched: found.searched,
        found: found.passages.length,
        documents: new Set(found.passages.map(documentKey)).size,
      }
    },
  }
}

import type { IconProp } from "@/components/forge/icons"

/** A model the agent can run on, picked from the composer's model section. */
export type AssistantModel = {
  /** Sent to the agent, e.g. "gemini-2.5-pro". */
  id: string
  name: string
  description?: string
  /**
   * Models with the same group are listed together under it, e.g. their
   * provider ("OpenAI"), in the order the groups first appear.
   */
  group?: string
  /** Shown before its name, e.g. its maker's mark. */
  icon?: IconProp
  /**
   * The ids of the thinking levels it offers, e.g. `["off"]` for a model
   * that doesn't reason. Default: every level of the model section.
   */
  thinkingLevels?: string[]
  /**
   * Its context window, and of it the most one reply may take, in tokens:
   * the context meter measures against them while it's the one chosen.
   */
  contextWindow?: number
  maxTokens?: number
}

/** How long the model thinks before it answers. */
export type ThinkingLevel = {
  /** Sent to the agent, e.g. "high". */
  id: string
  label: string
  description?: string
}

export const defaultThinkingLevels: ThinkingLevel[] = [
  { id: "off", label: "Off", description: "Answer straight away" },
  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Longest reasoning, for hard problems",
  },
]

/**
 * Every level a model provider configuration knows (model_provider.yaml, as
 * the coding agent and the Forge agent read it), from least to most thinking.
 * Pass it as `thinkingLevels` with models that say which they offer.
 */
export const extendedThinkingLevels: ThinkingLevel[] = [
  { id: "off", label: "Off", description: "Answer straight away" },
  { id: "minimal", label: "Minimal", description: "The briefest look first" },
  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Long reasoning, for hard problems",
  },
  {
    id: "xhigh",
    label: "Extra high",
    description: "Longest reasoning, for the hardest problems",
  },
]

/**
 * The level a model runs at when `id` is chosen: that one if it's among
 * `levels`, else the nearest above it in `order`, else the nearest below,
 * else the first. The same rule the server applies.
 */
export function nearestThinkingLevel(
  levels: ThinkingLevel[],
  order: ThinkingLevel[],
  id: string
): string | undefined {
  if (levels.some((level) => level.id === id)) return id
  const offered = new Set(levels.map((level) => level.id))
  const index = order.findIndex((level) => level.id === id)
  if (index >= 0) {
    const above = order.slice(index + 1).find((level) => offered.has(level.id))
    if (above) return above.id
    const below = order
      .slice(0, index)
      .reverse()
      .find((level) => offered.has(level.id))
    if (below) return below.id
  }
  return levels[0]?.id
}

/** What the model section has selected, sent with every run. */
export type ModelSelection = {
  model: string | undefined
  thinkingLevel: string
}

/**
 * The model section's choices and selection, from `useAdkAssistant`. Pass it
 * to `AssistantScreen` with `showModels`.
 */
export type ModelSettings = ModelSelection & {
  models: AssistantModel[]
  /** The selected model's levels. */
  thinkingLevels: ThinkingLevel[]
  setModel: (id: string) => void
  setThinkingLevel: (id: string) => void
  /**
   * Called by the model section while it's mounted: the selection is only
   * sent while someone can see it. Returns the cleanup.
   */
  show: () => () => void
}

/** The default ADK state delta: `model` and `thinking_level` session keys. */
export const defaultModelStateDelta = ({
  model,
  thinkingLevel,
}: ModelSelection): Record<string, unknown> => ({
  ...(model && { model }),
  thinking_level: thinkingLevel,
})

/*
 * Citation markers in an agent's answer: "[S3]", or "[S1, S3]", each naming a
 * passage by the ref its tool result gave it (see sources.tsx).
 */

/** "[S3]", or several at once: "[S1, S3]". */
const MARKER = /\[([A-Z]{1,3}\d{1,4}(?:\s*,\s*[A-Z]{1,3}\d{1,4})*)\]/g
export const REF_HREF = "#source-"

const refsIn = (marker: string) => marker.split(",").map((ref) => ref.trim())

/** The refs a text cites, first citation first. */
export function citedRefs(text: string): string[] {
  const refs = new Set<string>()
  for (const match of text.matchAll(MARKER)) {
    for (const ref of refsIn(match[1] ?? "")) refs.add(ref)
  }
  return [...refs]
}

type MdNode = {
  type: string
  value?: string
  url?: string
  children?: MdNode[]
}

/**
 * A remark plugin: each "[S3]" in the text becomes a link to `#source-S3`,
 * which `SourceAnchor` draws as a citation. Code and links are left alone.
 */
export function remarkSourceRefs() {
  return (tree: MdNode) => linkRefs(tree)
}

function linkRefs(node: MdNode): void {
  if (!node.children || node.type === "link" || node.type === "linkReference")
    return
  const children: MdNode[] = []
  for (const child of node.children) {
    const text = child.type === "text" ? (child.value ?? "") : ""
    let last = 0
    for (const match of text.matchAll(MARKER)) {
      const start = match.index ?? 0
      if (start > last) {
        // The space before a citation doesn't break: it stays with its word.
        const before = text.slice(last, start).replace(/ $/, "\u00a0")
        children.push({ type: "text", value: before })
      }
      for (const ref of refsIn(match[1] ?? "")) {
        children.push({
          type: "link",
          url: `${REF_HREF}${ref}`,
          children: [{ type: "text", value: `[${ref}]` }],
        })
      }
      last = start + match[0].length
    }
    if (last === 0) {
      linkRefs(child)
      children.push(child)
    } else if (last < text.length) {
      children.push({ type: "text", value: text.slice(last) })
    }
  }
  node.children = children
}

import * as React from "react"
import { useAuiState, type ThreadMessage } from "@assistant-ui/react"
import { cn } from "cn"

import { MarkdownText } from "@/components/assistant-ui/elements/markdown-text"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Icon } from "@/components/forge/icon"

import { useAssistantSettings } from "./assistant-context"
import { REF_HREF, citedRefs, remarkSourceRefs } from "./source-refs"

/*
 * Cited sources. An agent's tools return passages that each carry a ref
 * ("S3"); the agent cites them inline as "[S3]". The tool results stream with
 * the answer, in the same message, so the console resolves every ref from
 * them: no second channel, and the sources come back with the conversation.
 */

/** A document an answer can cite; its passages are listed together. */
export type AssistantSourceDocument = {
  /** Identifies the document. */
  key: string
  /** Its name, e.g. the filename. */
  title: string
  /** Where it's from, e.g. the team. */
  subtitle?: string
  /** Opens the document, in a new tab. */
  href?: string
}

/** A passage a tool returned, which the agent cites by `ref`. */
export type AssistantSource = {
  /** What the agent writes in brackets, e.g. "S3". */
  ref: string
  document: AssistantSourceDocument
  /** Where in the document: section, page, sheet. */
  location?: string
  /** The passage, shortened. */
  excerpt?: string
}

/** What a search call looked through and found, for its card. */
export type AssistantSearch = {
  /** What it searched, by name, e.g. the knowledge bases. */
  searched: string[]
  /** The passages it found; none when nothing was relevant enough. */
  found: number
  /** The documents they're from. */
  documents: number
}

/**
 * How answers cite what the agent's tools found. Make it once (at module
 * scope or in `useMemo`): each message's sources are read once per config.
 */
export type AssistantSourcesConfig = {
  /** The sources in a finished tool call's result; [] for other tools. */
  fromToolCall: (toolName: string, result: unknown) => AssistantSource[]
  /**
   * The search a finished tool call made, which its card says in place of
   * "Used tool: <name>" ("Searched Claims knowledge · 5 passages in 3
   * documents"); undefined for calls that aren't searches.
   */
  searchOf?: (toolName: string, result: unknown) => AssistantSearch | undefined
}

/* -------------------------------------------------------------------------- */
/* Where the refs point                                                       */
/* -------------------------------------------------------------------------- */

type Cached = { config: AssistantSourcesConfig; sources: AssistantSource[] }
// A message's sources, read once per version of it.
const perMessage = new WeakMap<ThreadMessage, Cached>()

function sourcesOf(
  message: ThreadMessage,
  config: AssistantSourcesConfig
): AssistantSource[] {
  const cached = perMessage.get(message)
  if (cached?.config === config) return cached.sources
  const sources: AssistantSource[] = []
  if (message.role === "assistant") {
    for (const part of message.content) {
      if (part.type !== "tool-call" || part.result === undefined) continue
      if (part.isError) continue
      try {
        sources.push(...config.fromToolCall(part.toolName, part.result))
      } catch {
        // A result the config can't read cites nothing.
      }
    }
  }
  perMessage.set(message, { config, sources })
  return sources
}

/** Every source the conversation's tools returned, by ref. */
function useThreadSources() {
  const config = useAssistantSettings().sources
  const messages = useAuiState((s) => s.thread.messages)
  return React.useMemo(() => {
    const byRef = new Map<string, AssistantSource>()
    if (config) {
      for (const message of messages) {
        for (const source of sourcesOf(message, config)) {
          byRef.set(source.ref, source)
        }
      }
    }
    return byRef
  }, [messages, config])
}

/** The refs this message cites, in order: [S7, S2] numbers S7 as 1. */
function useMessageCitations() {
  const text = useAuiState((s) =>
    s.message.content
      .map((part) => (part.type === "text" ? part.text : ""))
      .join("\n")
  )
  return React.useMemo(() => citedRefs(text), [text])
}

/* -------------------------------------------------------------------------- */
/* Citations in the text                                                      */
/* -------------------------------------------------------------------------- */

const chip =
  "inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-(--radius-chip) bg-muted px-1 font-sans text-3xs leading-none font-medium text-muted-foreground tabular-nums"

/**
 * A citation: its number in this answer, opening the passage behind it on
 * hover or press. A ref no tool returned stays the text the agent wrote.
 */
function SourceRef({ id }: { id: string }) {
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  const source = byRef.get(id)
  const number = cited.indexOf(id) + 1
  if (!source || number === 0) return <>{`[${id}]`}</>
  return (
    <Popover>
      {/* A span, not a button: an inline box keeps the no-break space
          before it, so a citation never wraps away from its word. */}
      <PopoverTrigger
        openOnHover
        delay={150}
        nativeButton={false}
        render={<span />}
        aria-label={`Source ${number}: ${source.document.title}`}
        className="relative -top-px ms-0.5 cursor-pointer rounded-(--radius-chip) bg-muted px-1 py-px font-sans text-3xs font-medium whitespace-nowrap text-muted-foreground tabular-nums transition-colors duration-100 hover:bg-accent hover:text-foreground data-popup-open:bg-accent data-popup-open:text-foreground"
      >
        {number}
      </PopoverTrigger>
      <PopoverContent side="top" align="start" className="w-80 gap-2">
        <SourceCard source={source} number={number} />
      </PopoverContent>
    </Popover>
  )
}

function SourceCard({
  source,
  number,
}: {
  source: AssistantSource
  number: number
}) {
  const { document } = source
  const where = [document.subtitle, source.location].filter(Boolean).join(" · ")
  return (
    <>
      <div className="flex min-w-0 items-start gap-2">
        <span className={cn(chip, "mt-px")}>{number}</span>
        <div className="grid min-w-0 gap-0.5">
          <p className="truncate font-medium text-foreground">
            {document.title}
          </p>
          {where && <p className="text-muted-foreground">{where}</p>}
        </div>
      </div>
      {source.excerpt && (
        <p className="line-clamp-4 text-muted-foreground">{source.excerpt}</p>
      )}
      {document.href && (
        <a
          href={document.href}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1 self-start font-medium text-foreground underline-offset-2 hover:underline"
        >
          Open document
          <Icon icon="external" size={13} />
        </a>
      )}
    </>
  )
}

/** Markdown links: citations from `remarkSourceRefs`, else a plain link. */
function SourceAnchor({
  href,
  className,
  children,
  ...props
}: React.ComponentProps<"a">) {
  if (href?.startsWith(REF_HREF))
    return <SourceRef id={href.slice(REF_HREF.length)} />
  return (
    <a
      href={href}
      className={cn(
        "aui-md-a text-primary underline underline-offset-2 hover:text-primary/80",
        className
      )}
      {...props}
    >
      {children}
    </a>
  )
}

const sourceComponents = { a: SourceAnchor }
const sourcePlugins = [remarkSourceRefs]

/** An answer's text, its "[S3]" citations drawn as numbered sources. */
export function SourcedMarkdownText() {
  const config = useAssistantSettings().sources
  if (!config) return <MarkdownText />
  return (
    <MarkdownText components={sourceComponents} remarkPlugins={sourcePlugins} />
  )
}

/* -------------------------------------------------------------------------- */
/* Sources under the answer                                                   */
/* -------------------------------------------------------------------------- */

type DocumentGroup = {
  document: AssistantSourceDocument
  sources: AssistantSource[]
}

function groupByDocument(sources: AssistantSource[]): DocumentGroup[] {
  const groups = new Map<string, DocumentGroup>()
  for (const source of sources) {
    const group = groups.get(source.document.key)
    if (group) group.sources.push(source)
    else
      groups.set(source.document.key, {
        document: source.document,
        sources: [source],
      })
  }
  return [...groups.values()]
}

function DocumentTitle({ document }: { document: AssistantSourceDocument }) {
  return document.href ? (
    <a
      href={document.href}
      target="_blank"
      rel="noreferrer"
      className="truncate font-medium text-foreground underline-offset-2 hover:underline"
    >
      {document.title}
    </a>
  ) : (
    <span className="truncate font-medium text-foreground">
      {document.title}
    </span>
  )
}

function DocumentRow({
  group,
  cited,
}: {
  group: DocumentGroup
  cited: boolean
}) {
  const locations = [
    ...new Set(group.sources.map((s) => s.location).filter(Boolean)),
  ]
  return (
    <li className="flex min-w-0 items-start gap-2 text-xs">
      {cited ? (
        <span className="mt-px flex shrink-0 gap-0.5">
          {group.sources.map((source) => (
            <SourceRef key={source.ref} id={source.ref} />
          ))}
        </span>
      ) : (
        <Icon
          icon="file"
          size={14}
          className="mt-px shrink-0 text-muted-foreground"
        />
      )}
      <div className="grid min-w-0 flex-1 gap-px">
        <div className="flex min-w-0 items-baseline gap-2">
          <DocumentTitle document={group.document} />
          {group.document.subtitle && (
            <span className="ms-auto shrink-0 text-2xs text-subtle">
              {group.document.subtitle}
            </span>
          )}
        </div>
        {locations.length > 0 && (
          <span className="truncate text-2xs text-muted-foreground">
            {locations.join(" · ")}
          </span>
        )}
      </div>
    </li>
  )
}

const plural = (count: number, one: string) =>
  `${count} ${one}${count === 1 ? "" : "s"}`

/* -------------------------------------------------------------------------- */
/* Search calls                                                               */
/* -------------------------------------------------------------------------- */

/**
 * A search call's card label: what it searched and what it found, e.g.
 * "Searched **Member knowledge** and **Claims knowledge** · 5 passages in 3
 * documents", or "· nothing relevant" when it found nothing to answer from.
 */
export function SearchLabel({ search }: { search: AssistantSearch }) {
  const [first, second, ...rest] = search.searched
  return (
    <>
      Searched {first ? <b>{first}</b> : "the knowledge base"}
      {second &&
        (rest.length ? (
          <> and {rest.length + 1} more</>
        ) : (
          <>
            {" "}
            and <b>{second}</b>
          </>
        ))}
      <span className="text-subtle">
        {" · "}
        {search.found
          ? `${plural(search.found, "passage")} in ${plural(search.documents, "document")}`
          : "nothing relevant"}
      </span>
    </>
  )
}

/**
 * The documents under an answer: the ones it cites, numbered as in the text,
 * then the others its searches found. Shown once the answer is complete.
 */
export function MessageSources() {
  const config = useAssistantSettings().sources
  const message = useAuiState((s) => s.message)
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  if (!config || message.role !== "assistant") return null
  if (message.status?.type === "running") return null

  const citedSources = cited.flatMap((ref) => byRef.get(ref) ?? [])
  const citedGroups = groupByDocument(citedSources)
  const citedKeys = new Set(citedGroups.map((g) => g.document.key))
  const searched = groupByDocument(sourcesOf(message, config)).filter(
    (g) => !citedKeys.has(g.document.key)
  )
  if (!citedGroups.length && !searched.length) return null

  return (
    <section
      aria-label="Sources"
      data-slot="assistant-message-sources"
      className="mt-3 grid gap-1.5 border-t border-border pt-2.5"
    >
      {citedGroups.length > 0 && (
        <>
          <p className="text-2xs font-medium text-muted-foreground">Sources</p>
          <ul className="grid gap-1.5">
            {citedGroups.map((group) => (
              <DocumentRow key={group.document.key} group={group} cited />
            ))}
          </ul>
        </>
      )}
      {searched.length > 0 && (
        <Collapsible>
          <CollapsibleTrigger className="group/searched inline-flex items-center gap-1 text-2xs font-medium text-muted-foreground hover:text-foreground">
            {citedGroups.length ? "Also searched" : "Searched"}{" "}
            {plural(searched.length, "document")}
            <Icon
              icon="down"
              size={13}
              className="transition-transform duration-150 group-data-panel-open/searched:rotate-180"
            />
          </CollapsibleTrigger>
          <CollapsibleContent>
            <ul className="mt-1.5 grid gap-1.5">
              {searched.map((group) => (
                <DocumentRow
                  key={group.document.key}
                  group={group}
                  cited={false}
                />
              ))}
            </ul>
          </CollapsibleContent>
        </Collapsible>
      )}
    </section>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
  WebSpeechDictationAdapter,
  type AssistantRuntime,
  type DictationAdapter,
  type FeedbackAdapter,
  type ThreadMessage,
} from "@assistant-ui/react"
import {
  createAdkSessionAdapter,
  createAdkStream,
  useAdkRuntime,
  type AdkEvent,
  type AdkStreamCallback,
  type UseAdkRuntimeOptions,
} from "@assistant-ui/react-google-adk"

import { followUpsRequest, type FollowUpsOption } from "./follow-ups"
import {
  defaultModelStateDelta,
  defaultThinkingLevels,
  nearestThinkingLevel,
  type AssistantModel,
  type ModelSelection,
  type ModelSettings,
  type ThinkingLevel,
} from "./model-settings"

type Headers = Record<string, string> | (() => Record<string, string>)

/** Fetch, list and delete a session's artifacts (direct ADK connections). */
export type AdkArtifactsApi = ReturnType<
  typeof createAdkSessionAdapter
>["artifacts"]

export type UseAdkAssistantOptions = Omit<
  UseAdkRuntimeOptions,
  "stream" | "sessionAdapter"
> & {
  /**
   * Proxy mode: your own API route, e.g. one built with `createAdkApiRoute`
   * from `@assistant-ui/react-google-adk/server`.
   */
  api?: string
  /**
   * Direct mode: an ADK server (`adk api_server`, `adk web`). Its sessions
   * become the thread list, and artifacts can be fetched.
   */
  adk?: { url: string; appName: string; userId: string }
  /** Sent with every request; a function is read per request. */
  headers?: Headers
  /**
   * ADK session state sent with every run, read as it's sent: e.g. what the
   * person is looking at, `() => ({ page_context: currentPage() })`. The
   * model section's keys win over the same keys here.
   */
  runState?: () => Record<string, unknown> | undefined
  /** A custom transport instead of `api` / `adk` (tests, mocks). */
  stream?: AdkStreamCallback
  /**
   * Voice input for the composer's mic button; the words appear in the input
   * as they're recognised. Default: the browser's own speech recognition
   * (Web Speech API), where the browser has it. `false` turns it off; any
   * assistant-ui `DictationAdapter` (e.g. a server speech-to-text) replaces it.
   */
  dictation?: boolean | DictationAdapter
  /**
   * Shows thumbs up / down on the agent's replies and receives each rating,
   * e.g. to store it next to the ADK session. Without it the buttons are
   * hidden.
   */
  onFeedback?: (feedback: AssistantFeedback) => void | Promise<void>
  /**
   * Models to choose from in the composer's model section (`showModels`).
   * They may arrive after the first render, e.g. from the agent server.
   */
  models?: AssistantModel[]
  /** Default: the first model. */
  defaultModel?: string
  /**
   * Thinking levels for the model section, from least to most thinking; a
   * model's own `thinkingLevels` narrows them. Default: off, low, medium,
   * high.
   */
  thinkingLevels?: ThinkingLevel[]
  /**
   * Default: "medium" when it's a level, otherwise the first. A model that
   * doesn't offer it gets the nearest level it does.
   */
  defaultThinkingLevel?: string
  /**
   * Turns the model section's selection into the ADK `stateDelta` sent with
   * each run. Default: `{ model, thinking_level }`.
   */
  modelStateDelta?: (selection: ModelSelection) => Record<string, unknown>
  /**
   * Asks the agent server for follow-up questions after each reply: every run
   * sends `forge:suggest_follow_ups` in its state (true, or `{ count }`, 1–5),
   * and once the turn ends with a reply, the server's model writes a few
   * messages the person might send next (forge_common's `FollowUpsPlugin`,
   * in Forge's agent runtimes). The thread shows them above the composer as
   * chips that send them. A server that doesn't know it ignores it, or refuses
   * the key if it checks the state it's sent.
   */
  suggestFollowUps?: FollowUpsOption
}

/**
 * The assistant-ui runtime for a Google ADK agent. Pass the result to
 * `AssistantScreen`: `runtime`, `artifacts` and the model section's
 * `modelSettings`.
 */
export function useAdkAssistant({
  api,
  adk,
  headers,
  runState,
  stream,
  dictation = true,
  onFeedback,
  models = noModels,
  defaultModel,
  thinkingLevels = defaultThinkingLevels,
  defaultThinkingLevel,
  modelStateDelta = defaultModelStateDelta,
  suggestFollowUps,
  ...options
}: UseAdkAssistantOptions) {
  // Headers may change (a refreshed token) without rebuilding the transport:
  // the getter is created once and reads the latest headers per request.
  const headersRef = useRef(headers)
  useEffect(() => {
    headersRef.current = headers
  })
  const [getHeaders] = useState(() => () => {
    const current = headersRef.current
    return typeof current === "function" ? current() : (current ?? {})
  })

  const { url, appName, userId } = adk ?? {}
  const connection = useMemo(() => {
    if (stream) return { stream }
    if (url && appName && userId) {
      const session = createAdkSessionAdapter({
        apiUrl: url,
        appName,
        userId,
        headers: getHeaders,
      })
      return {
        stream: createAdkStream({
          api: url,
          appName,
          userId,
          headers: getHeaders,
        }),
        sessionAdapter: session.adapter,
        load: session.load,
        artifacts: session.artifacts,
      }
    }
    if (api) return { stream: createAdkStream({ api, headers: getHeaders }) }
    throw new Error(
      "useAdkAssistant needs `api` (your route), `adk` (an ADK server) or `stream`."
    )
  }, [stream, url, appName, userId, api, getHeaders])

  const { settings: modelSettings, shown: modelsShown } = useModelSettings({
    models,
    defaultModel,
    thinkingLevels,
    defaultThinkingLevel,
  })

  // Runs carry `runState`, the request for follow-ups when they're on and,
  // while it's shown, the model section's selection as ADK state.
  const selectionRef = useRef<ModelSelection | undefined>(undefined)
  const toStateDeltaRef = useRef(modelStateDelta)
  const runStateRef = useRef(runState)
  const followUpsRef = useRef(suggestFollowUps)
  useEffect(() => {
    const { model, thinkingLevel } = modelSettings
    selectionRef.current = modelsShown ? { model, thinkingLevel } : undefined
    toStateDeltaRef.current = modelStateDelta
    runStateRef.current = runState
    followUpsRef.current = suggestFollowUps
  })
  const send = useCallback<AdkStreamCallback>(
    async function* (messages, config) {
      const selection = selectionRef.current
      try {
        const state = runStateRef.current?.()
        const followUps = followUpsRequest(followUpsRef.current)
        yield* await connection.stream(
          messages,
          selection || state || followUps
            ? {
                ...config,
                stateDelta: {
                  ...config.stateDelta,
                  ...state,
                  ...followUps,
                  ...(selection && toStateDeltaRef.current(selection)),
                },
              }
            : config
        )
      } catch (error) {
        // Stop aborts the run; that isn't a failure to show.
        if (config.abortSignal.aborted) throw error
        // The SDK would drop the error and leave the thread silent; as an ADK
        // error event it shows as a failed reply, like the agent's own errors.
        yield requestFailed(error)
      }
    },
    [connection]
  )

  // Created once: the browser adapter starts a fresh recognition per session.
  const [browserDictation] = useState(() =>
    WebSpeechDictationAdapter.isSupported()
      ? new WebSpeechDictationAdapter()
      : undefined
  )
  const dictationAdapter =
    dictation === true ? browserDictation : dictation || undefined
  // Created once: reads the latest handler and session for each rating.
  const onFeedbackRef = useRef(onFeedback)
  const runtimeRef = useRef<AssistantRuntime | null>(null)
  // Only direct connections know ADK session ids; other threads are local.
  const sessionsRef = useRef(false)
  const [feedbackAdapter] = useState<FeedbackAdapter>(() => ({
    submit: ({ message, type, comment }) => {
      const feedback: AssistantFeedback = {
        type,
        message,
        text: messageText(message),
        sessionId: sessionsRef.current
          ? runtimeRef.current?.threads.mainItem.getState().remoteId
          : undefined,
        ...(comment && { comment }),
      }
      Promise.resolve()
        .then(() => onFeedbackRef.current?.(feedback))
        .catch((error: unknown) => console.error("Feedback failed:", error))
    },
  }))
  const hasFeedback = Boolean(onFeedback)

  const adapters = useMemo(
    () => ({
      dictation: dictationAdapter,
      ...(hasFeedback && { feedback: feedbackAdapter }),
      ...options.adapters,
    }),
    [dictationAdapter, hasFeedback, feedbackAdapter, options.adapters]
  )

  const runtime = useAdkRuntime({
    ...options,
    adapters,
    stream: send,
    sessionAdapter: connection.sessionAdapter,
    load: options.load ?? connection.load,
  })
  useEffect(() => {
    onFeedbackRef.current = onFeedback
    runtimeRef.current = runtime
    sessionsRef.current = Boolean(connection.sessionAdapter)
  })

  return {
    runtime,
    artifacts: connection.artifacts,
    modelSettings,
  }
}

/** A thumbs up or down on one of the agent's replies. */
export type AssistantFeedback = {
  type: "positive" | "negative"
  /** The rated reply. */
  message: ThreadMessage
  /** The reply's text, for logs and review queues. */
  text: string
  /** The reply's ADK session, for direct `adk` connections once it exists. */
  sessionId: string | undefined
  /** A comment, when the UI collects one. */
  comment?: string
}

/** A failed request to the agent server (unreachable, refused, not found) as an ADK error event. */
const requestFailed = (error: unknown): AdkEvent => ({
  id: crypto.randomUUID(),
  errorCode: "REQUEST_FAILED",
  errorMessage: `The assistant couldn't reach the agent: ${
    error instanceof Error ? error.message : String(error)
  }`,
})

const messageText = (message: ThreadMessage) =>
  message.content
    .flatMap((part) => (part.type === "text" ? [part.text] : []))
    .join("\n\n")

const noModels: AssistantModel[] = []

function useModelSettings({
  models,
  defaultModel,
  thinkingLevels,
  defaultThinkingLevel,
}: {
  models: AssistantModel[]
  defaultModel: string | undefined
  thinkingLevels: ThinkingLevel[]
  defaultThinkingLevel: string | undefined
}) {
  // What the person chose; what's selected follows the models as they load
  // or change: the choice while it's one of them, else the default, else
  // the first.
  const [chosenModel, setModel] = useState<string>()
  const [chosenLevel, setThinkingLevel] = useState<string>()
  const listed = (id: string | undefined) =>
    id !== undefined && models.some((option) => option.id === id)
  const model = listed(chosenModel)
    ? chosenModel
    : listed(defaultModel)
      ? defaultModel
      : (models[0]?.id ?? defaultModel)

  // As a string, so a new array with the same levels keeps the same list.
  const offered = models
    .find((option) => option.id === model)
    ?.thinkingLevels?.join(" ")
  const modelLevels = useMemo(() => {
    if (offered === undefined) return thinkingLevels
    const ids = offered.split(" ")
    return thinkingLevels.filter((level) => ids.includes(level.id))
  }, [thinkingLevels, offered])
  const preferred =
    chosenLevel ??
    defaultThinkingLevel ??
    (thinkingLevels.some((level) => level.id === "medium")
      ? "medium"
      : (thinkingLevels[0]?.id ?? ""))
  const thinkingLevel =
    nearestThinkingLevel(modelLevels, thinkingLevels, preferred) ?? preferred

  const [shownBy, setShownBy] = useState(0)
  const show = useCallback(() => {
    setShownBy((count) => count + 1)
    return () => setShownBy((count) => count - 1)
  }, [])

  const settings = useMemo<ModelSettings>(
    () => ({
      models,
      thinkingLevels: modelLevels,
      model,
      thinkingLevel,
      setModel,
      setThinkingLevel,
      show,
    }),
    [models, modelLevels, model, thinkingLevel, show]
  )
  return { settings, shown: shownBy > 0 }
}
